// These are not stored in the database — they are calculated from the raw data
// for display purposes.

/**
 * Attendance summary for a single event, computed from EventWithDetails.
 * Used to drive the join/leave button states and spot count badges.
 */
export type AttendanceStatus = {
  count: number           // Total number of attendees currently signed up
  spotsLeft: number | null  // Remaining spots; null if the event has no cap
  isFull: boolean         // true when count >= max_attendees (and max_attendees is set)
  isAttending: boolean    // true if the current logged-in user is in event_attendees with status='attending'
  isOwner: boolean        // true if the current logged-in user created the event
  isWaitlisted: boolean       // true if the current user is on the waitlist
  waitlistPosition: number | null  // 1-based position on waitlist; null if not waitlisted
  waitlistCount: number       // total number of people on the waitlist
  isRequested: boolean        // true if the current user has a pending join request (paid events)
  isDenied: boolean           // true if the current user's request was denied
  denialReason: string | null // reason provided by host when denying; null if none given
}

/** A player's team placement on the event People/Cheers tabs. */
export type TeamAssignment = { team: number | null; pinned: boolean }

/**
 * How the viewer is connected to an upcoming event, for the "You're going" rail.
 * Ordered by commitment: hosting outranks attending, which outranks waitlisted.
 */
export type MyEventStatus = 'hosting' | 'attending' | 'waitlisted' | 'requested'

/** One card in the "You're going" rail — an event plus the viewer's relationship to it. */
export type MyUpcomingEvent = {
  event: EventWithDetails
  status: MyEventStatus
  /** 1-based waitlist position, hydrated separately. Null until known or when not waitlisted. */
  waitlistPosition: number | null
  /** True while the event is underway — started, but not yet past its duration. */
  inProgress: boolean
}

